\begin{theorem}\label{thm:main}
Let $G$ be a graph with $n$ vertices and $m$ edges. Let $d$ be a
$L^2$-metric on $G$. Then
\[
\beta_i(G,d)\leq \frac{n}{2}\binom{n-1}{i-1}
\]
for all $i\geq 1$.
\end{theorem}

\begin{remark}
The bound in Theorem \ref{thm:main} is sharp. For example, the
complete graph $K_n$ with the $L^2$-metric $d$ defined by
\[
d(x,y)=\begin{cases}
\frac{1}{2} & \text{if $x=y$}\\
1 & \text{otherwise}
\end{cases}
\]
has $L^2$-Betti numbers $\beta_i(K_n,d)=n$ for all $i\geq 1$.
\end{remark}

